// Dibuja el QR (negro sobre fondo blanco) con el tamano de cada cuadrito "escala"
void dibujarQR(int x0, int y0, int escala, int borde) {
  int lado = qrN * escala + 2 * borde;
  disp.fillRect(x0, y0, lado, lado, SSD1306_WHITE);
  for (int y = 0; y < qrN; y++) for (int x = 0; x < qrN; x++)
    if (qrMod[y][x]) disp.fillRect(x0 + borde + x * escala, y0 + borde + y * escala, escala, escala, SSD1306_BLACK);
}

