// Parte el texto en lineas de "cols" letras sin cortar palabras
int envolver(const char* s, int cols, int* ini, int maxL) {
  int n = strlen(s), i = 0, c = 0;
  while (i < n && c < maxL - 1) {
    while (i < n && s[i] == ' ') i++;
    if (i >= n) break;
    ini[c++] = i;
    int fin = i + cols;
    if (fin >= n) { i = n; break; }
    int corte = fin;
    while (corte > i && s[corte] != ' ') corte--;
    if (corte == i) corte = fin;
    i = corte;
  }
  ini[c] = n;
  return c;
}

void mostrarBurbuja(const char* t) {
  strncpy(bub, t, sizeof(bub) - 1); bub[sizeof(bub) - 1] = 0;
  bubN = envolver(bub, 21, bubIni, 10);
  int paginas = (bubN + 1) / 2; if (paginas < 1) paginas = 1;
  bubAct = true; bubT0 = millis(); bubDur = paginas * 3200UL;
}

// ---- piezas para dibujar ----
void ojoRect(int cx, int cy, int w, int h, int r) {
  if (h < 3) h = 3;
  if (r > h / 2) r = h / 2;
  disp.fillRoundRect(cx - w / 2, cy - h / 2, w, h, r, SSD1306_WHITE);
}
void parpadoPlano(int cx, int cy, int w, int h, int cuanto) {      // tapa la parte de arriba del ojo
  disp.fillRect(cx - w / 2 - 1, cy - h / 2 - 1, w + 2, cuanto + 1, SSD1306_BLACK);
}
void arcoArriba(int cx, int cy, int w) {                            // ojo feliz  ^
  int m = w / 2;
  for (int x = -m; x <= m; x++) {
    float u = (float)x / m;
    int y = cy + 5 - (int)(10.0f * sqrtf(1.0f - u * u));
    disp.drawFastVLine(cx + x, y, 4, SSD1306_WHITE);
  }
}
void arcoAbajo(int cx, int cy, int w) {                             // ojo cerrado  u
  int m = w / 2;
  for (int x = -m; x <= m; x++) {
    float u = (float)x / m;
    int y = cy - 3 + (int)(6.0f * sqrtf(1.0f - u * u));
    disp.drawFastVLine(cx + x, y, 3, SSD1306_WHITE);
  }
}
void bocaSonrisa(int cx, int y, int m, int prof) {
  for (int x = -m; x <= m; x++) disp.drawFastVLine(cx + x, y + prof - prof * x * x / (m * m), 2, SSD1306_WHITE);
}
void bocaTriste(int cx, int y, int m, int prof) {
  for (int x = -m; x <= m; x++) disp.drawFastVLine(cx + x, y + prof * x * x / (m * m), 2, SSD1306_WHITE);
}
void corazon(int x, int y) {
  disp.fillCircle(x - 2, y, 2, SSD1306_WHITE);
  disp.fillCircle(x + 2, y, 2, SSD1306_WHITE);
  disp.fillTriangle(x - 4, y + 1, x + 4, y + 1, x, y + 6, SSD1306_WHITE);
}
void gota(int x, int y) {
  disp.fillCircle(x, y + 3, 2, SSD1306_WHITE);
  disp.fillTriangle(x - 2, y + 2, x + 2, y + 2, x, y - 3, SSD1306_WHITE);
}
void bocaO(int cx, int y, int r) {
  disp.fillCircle(cx, y, r, SSD1306_WHITE);
  if (r > 2) disp.fillCircle(cx, y, r - 2, SSD1306_BLACK);
}

// Dibuja la cara completa. "t" = ms desde que empezo este animo. "burb" = hay burbuja de texto abajo.
void dibujarCara(int a, unsigned long t, bool burb, bool habla) {
  unsigned long ahora = millis();
  if (ahora > proxMirada) { tgtX = random(-7, 8); tgtY = random(-3, 4); proxMirada = ahora + random(1800, 4500); }
  lookX += (tgtX - lookX) * 0.25f; lookY += (tgtY - lookY) * 0.25f;
  float abierto = 1.0f;
  if (ahora >= proxBlink) { blinkIni = ahora; proxBlink = ahora + random(2200, 5500); }
  if (ahora - blinkIni < 160) abierto = fabsf(1.0f - 2.0f * (ahora - blinkIni) / 160.0f);

  int W = burb ? 24 : 28, H = burb ? 24 : 32;
  int cy = burb ? 15 : 24;
  int by = burb ? 37 : 50;                                         // altura de la boca
  int dx = (int)lookX, dy = (int)lookY;
  int sx = 0, sy = 0;
  int L = 36, R = 92;
  int ph;

  switch (a) {
    case A_NEUTRO: {
      int h = (int)(H * abierto);
      ojoRect(L + dx, cy + dy, W, h, 9); ojoRect(R + dx, cy + dy, W, h, 9);
      if (habla && (ahora / 140) % 2) bocaO(64 + dx / 2, by, 3);
      else bocaSonrisa(64 + dx / 2, by - 2, 7, 3);
      break;
    }
    case A_FELIZ: {
      sy = -(int)(3.0f * fabsf(sinf(t / 110.0f)));
      ojoRect(L, cy + sy, W + 2, H + 2, 10); ojoRect(R, cy + sy, W + 2, H + 2, 10);
      disp.fillRect(L + 3, cy + sy - 11, 4, 4, SSD1306_BLACK);    // brillitos
      disp.fillRect(R + 3, cy + sy - 11, 4, 4, SSD1306_BLACK);
      disp.fillRect(L + 8, cy + sy - 5, 2, 2, SSD1306_BLACK);
      disp.fillRect(R + 8, cy + sy - 5, 2, 2, SSD1306_BLACK);
      if (habla && (ahora / 140) % 2) bocaO(64, by + sy, 3);
      else {
        disp.fillCircle(64, by - 3 + sy, 8, SSD1306_WHITE);        // sonrisa grande
        disp.fillRect(64 - 9, by - 3 + sy - 9, 19, 9, SSD1306_BLACK);
      }
      break;
    }
    case A_AMOR: {
      arcoArriba(L, cy + 2, W - 2); arcoArriba(R, cy + 2, W - 2);
      bocaSonrisa(64 - 5, by - 3, 5, 3); bocaSonrisa(64 + 5, by - 3, 5, 3);   // boquita de gatito
      if (!burb) for (int i = 0; i < 3; i++) {                                // mejillas rojas
        disp.drawLine(L - 14 + i * 4, cy + 13, L - 11 + i * 4, cy + 17, SSD1306_WHITE);
        disp.drawLine(R + 4 + i * 4, cy + 13, R + 7 + i * 4, cy + 17, SSD1306_WHITE);
      }
      for (int k = 0; k < 2; k++) {                                           // corazones que suben
        ph = (int)((t / 45 + k * 20) % 40);
        int hy = 42 - ph; if (hy > 1) corazon(k ? 118 : 10, hy);
      }
      break;
    }
    case A_TRISTE: {
      int h = (int)((H - 4) * abierto);
      ojoRect(L + dx / 2, cy + 3, W, h, 9); ojoRect(R + dx / 2, cy + 3, W, h, 9);
      int top = cy + 3 - h / 2;
      disp.fillTriangle(L - W / 2 - 1 + dx / 2, top - 1, L + W / 2 + 1 + dx / 2, top - 1, L - W / 2 - 1 + dx / 2, top + 11, SSD1306_BLACK);
      disp.fillTriangle(R + W / 2 + 1 + dx / 2, top - 1, R - W / 2 - 1 + dx / 2, top - 1, R + W / 2 + 1 + dx / 2, top + 11, SSD1306_BLACK);
      bocaTriste(64, by - 1, 7, 3);
      ph = (int)((t / 50) % 70);
      if (ph < 36) gota(L - 8, cy + 12 + ph / 2);
      break;
    }
    case A_CANSADO: {
      int h = (int)(18 * abierto) + 2;
      ojoRect(L + dx / 2, cy + 5, W, h, 6); ojoRect(R + dx / 2, cy + 5, W, h, 6);
      parpadoPlano(L + dx / 2, cy + 5, W, h, h * 4 / 10); parpadoPlano(R + dx / 2, cy + 5, W, h, h * 4 / 10);
      disp.drawFastHLine(64 - 5, by, 10, SSD1306_WHITE);
      break;
    }
    case A_DORMIDO: {
      arcoAbajo(L, cy + 4, W - 2); arcoAbajo(R, cy + 4, W - 2);
      bocaO(64, by, (sinf(t / 700.0f) > 0.2f) ? 3 : 2);                       // respira
      disp.setTextColor(SSD1306_WHITE);
      for (int k = 0; k < 3; k++) {                                           // zzz que suben
        ph = (int)((t / 40 + k * 30) % 90);
        if (ph < 80) { disp.setTextSize(k % 2 ? 1 : 2); disp.setCursor(96 + ph / 5, 30 - ph / 3); disp.print("Z"); }
      }
      disp.setTextSize(1);
      break;
    }
    case A_FRIO: {
      sx = ((t / 55) % 2) ? 2 : -2;                                           // tiembla
      int h = 14;
      ojoRect(L + sx, cy + 4, W - 2, h, 5); ojoRect(R + sx, cy + 4, W - 2, h, 5);
      for (int i = 0; i < 6; i++) disp.drawLine(54 + sx + i * 4, by + (i % 2 ? 2 : -2), 58 + sx + i * 4, by + ((i + 1) % 2 ? 2 : -2), SSD1306_WHITE);
      disp.drawLine(112, 4, 112, 14, SSD1306_WHITE);                          // copito de nieve
      disp.drawLine(107, 6, 117, 12, SSD1306_WHITE);
      disp.drawLine(107, 12, 117, 6, SSD1306_WHITE);
      disp.drawLine(6, 22, 11, 28, SSD1306_WHITE); disp.drawLine(6, 28, 11, 34, SSD1306_WHITE);   // rayitas de temblor
      break;
    }
    case A_CALOR: {
      int h = 22;
      ojoRect(L, cy + 4, W, h, 6); ojoRect(R, cy + 4, W, h, 6);
      parpadoPlano(L, cy + 4, W, h, h * 4 / 10); parpadoPlano(R, cy + 4, W, h, h * 4 / 10);
      disp.drawFastHLine(64 - 9, by - 1, 19, SSD1306_WHITE);                  // boca abierta con lengua
      int lg = 6 + (int)(3.0f * sinf(t / 180.0f));
      disp.fillRoundRect(64 - 1, by - 1, 8, lg, 3, SSD1306_WHITE);
      ph = (int)((t / 40) % 44); gota(118, 6 + ph);
      ph = (int)((t / 40 + 22) % 44); gota(8, 6 + ph);
      break;
    }
    case A_SORPRESA: {
      ojoRect(L, cy, W + 4, H + 6, 12); ojoRect(R, cy, W + 4, H + 6, 12);
      disp.fillCircle(L + dx / 3, cy, 4, SSD1306_BLACK); disp.fillCircle(R + dx / 3, cy, 4, SSD1306_BLACK);
      bocaO(64, by + 1, 5);
      break;
    }
    case A_BOSTEZO: {
      float p = t / 1500.0f; if (p > 1) p = 1;
      for (int k = 0; k < 2; k++) {                                           // ojos apretados  > <
        disp.drawLine(L - 9, cy - 8 + k, L + 5, cy + k, SSD1306_WHITE); disp.drawLine(L - 9, cy + 8 + k, L + 5, cy + k, SSD1306_WHITE);
        disp.drawLine(R + 9, cy - 8 + k, R - 5, cy + k, SSD1306_WHITE); disp.drawLine(R + 9, cy + 8 + k, R - 5, cy + k, SSD1306_WHITE);
      }
      int hh = 4 + (int)(16.0f * sinf(3.14159f * p));
      if (burb) hh = hh * 2 / 3;
      disp.drawRoundRect(64 - 9, by - hh / 2 - 1, 18, hh + 2, 6, SSD1306_WHITE);
      break;
    }
    default: {                                                                // A_PENSANDO
      int h = (int)(H * abierto);
      ojoRect(L + 8, cy - 5, W, h, 9); ojoRect(R + 8, cy - 5, W, h, 9);
      disp.drawFastHLine(64 - 4, by, 8, SSD1306_WHITE);
      int pts = (int)((t / 300) % 4);
      for (int i = 0; i < pts; i++) disp.fillCircle(102 + i * 7, burb ? 30 : 56, 2, SSD1306_WHITE);
      break;
    }
  }
}
char cuerpo[2800];

// Anexa texto tal cual (partes fijas del JSON)
void rawAdd(int& n, const char* s) {
  int cap = sizeof(cuerpo);
  while (*s && n < cap - 1) cuerpo[n++] = *s++;
  cuerpo[n] = 0;
}
// Anexa texto escapando comillas y barras (contenido del usuario / IA)
void escAdd(int& n, const char* s) {
  int cap = sizeof(cuerpo);
  for (; *s; s++) {
    char c = *s;
    if (c == '"' || c == '\\') { if (n + 2 >= cap) break; cuerpo[n++] = '\\'; cuerpo[n++] = c; }
    else if ((unsigned char)c >= 32) { if (n + 1 >= cap) break; cuerpo[n++] = c; }
  }
  cuerpo[n] = 0;
}
// memoria del chat: ultimas 3 preguntas y respuestas
const int MAXH = 3;
char histU[MAXH][64];
char histM[MAXH][240];
int nHist = 0;
void agregarHist(const char* u, const char* m) {
  if (nHist == MAXH) {
    for (int i = 0; i < MAXH - 1; i++) { memcpy(histU[i], histU[i + 1], 64); memcpy(histM[i], histM[i + 1], 240); }
    nHist = MAXH - 1;
  }
  strncpy(histU[nHist], u, 63); histU[nHist][63] = 0;
  strncpy(histM[nHist], m, 239); histM[nHist][239] = 0;
  nHist++;
}
void jsonCont(int& n, const char* rol, const char* t) {
  rawAdd(n, "{\"role\":\""); rawAdd(n, rol);
  rawAdd(n, "\",\"parts\":[{\"text\":\""); escAdd(n, t);
  rawAdd(n, "\"}]}");
}
char resp[500], tmp[500];
// --- Lector que va sacando el ultimo "text":"..." de la respuesta JSON ---
int ntmp = 0;
int estJ = 0;          // 0 buscando, 1 saltando espacios, 2 leyendo texto
int kj = 0;
bool escJ = false;
int uHex = -1; unsigned uVal = 0;
int u8falta = 0; unsigned u8cp = 0;
bool cortada = false;  // Google aviso que la respuesta se corto (MAX_TOKENS)
int mxk = 0;

char aAscii(unsigned cp) {
  if (cp >= 32 && cp < 127) return (char)cp;
  switch (cp) {
    case 0xE1: case 0xE0: case 0xE4: return 'a';
    case 0xE9: case 0xE8: case 0xEB: return 'e';
    case 0xED: case 0xEC: case 0xEF: return 'i';
    case 0xF3: case 0xF2: case 0xF6: return 'o';
    case 0xFA: case 0xF9: case 0xFC: return 'u';
    case 0xF1: return 'n';
    case 0xC1: return 'A'; case 0xC9: return 'E'; case 0xCD: return 'I';
    case 0xD3: return 'O'; case 0xDA: case 0xDC: return 'U'; case 0xD1: return 'N';
    case 0x2013: case 0x2014: return '-';
    case 0x2018: case 0x2019: return '\'';
    case 0x201C: case 0x201D: return '"';
    case 0xD7: return 'x';
    case 10: case 13: return ' ';
  }
  return 0;
}

void salidaCaracter(unsigned cp) {
  char c = aAscii(cp);
  if (c && ntmp < (int)sizeof(tmp) - 1) tmp[ntmp++] = c;
}

void jsonByte(uint8_t b) {
  const char* maxt = "MAX_TOKENS";                       // detecta respuestas cortadas
  if (b == (uint8_t)maxt[mxk]) { mxk++; if (maxt[mxk] == 0) { cortada = true; mxk = 0; } }
  else mxk = (b == 'M') ? 1 : 0;

  const char* clave = "\"text\":";
  if (estJ == 0) {
    if (b == (uint8_t)clave[kj]) { kj++; if (clave[kj] == 0) { estJ = 1; kj = 0; } }
    else kj = (b == '"') ? 1 : 0;
    return;
  }
  if (estJ == 1) {
    if (b == ' ') return;
    if (b == '"') { estJ = 2; ntmp = 0; escJ = false; uHex = -1; u8falta = 0; }
    else estJ = 0;
    return;
  }
  if (uHex >= 0) {
    uVal = uVal * 16 + (b <= '9' ? b - '0' : (b | 32) - 'a' + 10);
    if (++uHex == 4) { salidaCaracter(uVal); uHex = -1; }
    return;
  }
  if (escJ) {
    escJ = false;
    if (b == 'u') { uHex = 0; uVal = 0; }
    else if (b == 'n' || b == 'r' || b == 't') salidaCaracter(' ');
    else salidaCaracter(b);
    return;
  }
  if (b == '\\') { escJ = true; return; }
  if (b == '"') {
    tmp[ntmp] = 0;
    if (ntmp > 0) { strncpy(resp, tmp, sizeof(resp) - 1); resp[sizeof(resp) - 1] = 0; }
    estJ = 0; kj = 0;
    return;
  }
  if (b < 0x80) { salidaCaracter(b); return; }
  if (u8falta > 0) {
    u8cp = (u8cp << 6) | (b & 0x3F);
    if (--u8falta == 0) salidaCaracter(u8cp);
    return;
  }
  if ((b & 0xE0) == 0xC0) { u8cp = b & 0x1F; u8falta = 1; }
  else if ((b & 0xF0) == 0xE0) { u8cp = b & 0x0F; u8falta = 2; }
  else if ((b & 0xF8) == 0xF0) { u8cp = b & 0x07; u8falta = 3; }
}

bool enLlamada = false;

// Una llamada a Gemini. Devuelve 0 si salio bien o un codigo de error (resultado en "resp").
int llamarGeminiUna(const char* sistema, bool memoria, const char* usuario, int maxTokens, const char* nivel) {
  resp[0] = 0; ntmp = 0; estJ = 0; kj = 0; cortada = false; mxk = 0;
  if (!hayKey()) return -5;
  if (apActivo() || WiFi.status() != WL_CONNECTED) return -1;

  int n = 0;
  cuerpo[0] = 0;
  rawAdd(n, "{\"system_instruction\":{\"parts\":[{\"text\":\"");
  escAdd(n, sistema);
  rawAdd(n, "\"}]},\"contents\":[");
  if (memoria) {
    for (int i = 0; i < nHist; i++) {
      jsonCont(n, "user", histU[i]); rawAdd(n, ",");
      jsonCont(n, "model", histM[i]); rawAdd(n, ",");
    }
  }
  jsonCont(n, "user", usuario);
  rawAdd(n, "],\"generationConfig\":{\"maxOutputTokens\":");
  char mt[8]; snprintf(mt, sizeof(mt), "%d", maxTokens);
  rawAdd(n, mt);
  rawAdd(n, ",\"thinkingConfig\":{\"thinkingLevel\":\"");
  rawAdd(n, nivel);
  rawAdd(n, "\"}}}");

  char ruta[96];
  snprintf(ruta, sizeof(ruta), "/v1beta/models/%s:generateContent", MODELOS[modeloIdx]);

  WiFiClientSecure cli;
  cli.setInsecure();
  if (!cli.connect("generativelanguage.googleapis.com", 443, 8000)) return -2;
  cli.print("POST "); cli.print(ruta);
  cli.print(" HTTP/1.1\r\nHost: generativelanguage.googleapis.com\r\n");
  cli.print("x-goog-api-key: "); cli.print(keyActual()); cli.print("\r\n");
  cli.print("Content-Type: application/json\r\nConnection: close\r\nContent-Length: ");
  char largo[12];
  snprintf(largo, sizeof(largo), "%d", (int)strlen(cuerpo));
  cli.print(largo);
  cli.print("\r\n\r\n");
  cli.print(cuerpo);

  int estado = 0, fase = 0;
  char linea[48]; int nl = 0;
  bool chunked = false;
  int cs = 0; long cres = 0;
  unsigned long ini = millis();
  while ((cli.connected() || cli.available()) && millis() - ini < 25000UL) {
    if (!cli.available()) { delay(5); continue; }
    uint8_t b = cli.read();
    if (fase < 2) {
      if (b == '\n') {
        linea[nl] = 0;
        if (fase == 0) { if (nl > 12) estado = atoi(linea + 9); fase = 1; }
        else if (nl == 0 || (nl == 1 && linea[0] == '\r')) fase = 2;
        else {
          for (int i = 0; i < nl; i++) linea[i] = tolower(linea[i]);
          if (strstr(linea, "transfer-encoding") && strstr(linea, "chunked")) chunked = true;
        }
        nl = 0;
      } else if (nl < (int)sizeof(linea) - 1) linea[nl++] = b;
      continue;
    }
    if (!chunked) { jsonByte(b); continue; }
    if (cs == 0) {
      if (b == '\n') { cs = (cres == 0) ? 3 : 1; }
      else if (isxdigit(b)) cres = cres * 16 + (b <= '9' ? b - '0' : (b | 32) - 'a' + 10);
    } else if (cs == 1) {
      jsonByte(b);
      if (--cres == 0) cs = 2;
    } else if (cs == 2) {
      if (b == '\n') { cs = 0; cres = 0; }
    } else break;
  }
  cli.stop();

  if (estado != 200) return estado > 0 ? estado : -3;
  if (resp[0] == 0) return -4;
  return 0;
}

// Si el modo RAPIDO no lo acepta el modelo (error 400), vuelve al modo normal solo.
int llamarGemini(const char* sistema, bool memoria, const char* usuario, int maxTokens) {
  int e = llamarGeminiUna(sistema, memoria, usuario, maxTokens, rapido ? "minimal" : "low");
  if (e == 400 && rapido) {
    rapido = false;
    guardarAjustes();
    e = llamarGeminiUna(sistema, memoria, usuario, maxTokens, "low");
  }
  return e;
}

const char* textoError(int e) {
  switch (e) {
    case -1: return apActivo() ? "No hay internet en mi WiFi propio" : "No hay WiFi";
    case -5: return "Falta la API key";
    case -2: return "No conecta con Google";
    case -3: return "Google no respondio";
    case -4: return "Respuesta vacia";
    case 400: return "Error 400 (peticion o key mala)";
    case 401: case 403: return "La API key no es valida";
    case 404: return "El modelo no existe, cambialo en ajustes";
    case 429: return "Muchas preguntas, espera 1 minuto";
    case 503: return "Google saturado, prueba otro modelo";
    default: return "Error del servidor";
  }
}

// Deja la frase limpia y corta para la pantallita
void limpiarFrase(char* s, int maxc) {
  char* w = s;
  for (char* r = s; *r; r++) { if (*r == '"' || *r == '*' || *r == '\n' || *r == '|') continue; *w++ = *r; }
  *w = 0;
  int ini = 0; while (s[ini] == ' ') ini++;
  if (ini) memmove(s, s + ini, strlen(s + ini) + 1);
  int l = strlen(s);
  while (l > 0 && s[l - 1] == ' ') s[--l] = 0;
  if (l > maxc) { int c = maxc; while (c > 10 && s[c] != ' ') c--; s[c] = 0; }
}

