void anotarFrase(const char* f) {
  if (nFrases == 4) { for (int i = 0; i < 3; i++) memcpy(frasesRec[i], frasesRec[i + 1], 48); nFrases = 3; }
  strncpy(frasesRec[nFrases], f, 47); frasesRec[nFrases][47] = 0; nFrases++;
}
