}
void solicitarHabla(int ev, unsigned long enMs) { evPend = ev; evCuando = millis() + enMs; }

void decirEvento(int ev) {
  unsigned long ahora = millis();
  if (evUlt[ev] && ahora - evUlt[ev] < EV_ESPERA[ev]) return;
  if (ev != EV_HOLA && ahora - ultHabla < 12000UL) return;      // no hablar encima de lo anterior
  if (pagina != 0 || modo != M_PET) return;
  evUlt[ev] = ahora; ultHabla = ahora;
  char frase[120]; frase[0] = 0;
  bool ia = hablaIA && hayKey() && !apActivo() && WiFi.status() == WL_CONNECTED && ev != EV_DUERME && !enLlamada && llamadasHora() < MAX_LLAM_HORA;
  if (ia) {
    forzarAnimo(A_PENSANDO, 30000UL);
    sndPensando();
    animoPrev = A_PENSANDO; animoIni = millis();
    dibujar();                                                  // se ve "pensando" mientras espera a Gemini
    char sis[420], usr[640], est[140];
    snprintf(sis, sizeof(sis), "%s Te llamas %s. Eres un robotito mascota que vive en una pantallita y le hablas a tu duena. "
             "Responde con UNA sola frase muy corta en espanol (maximo 45 caracteres), sin apodos, sin emojis, sin acentos, sin comillas y sin markdown.",
             PERS_SYS[personalidad], nombre);
    estadoTexto(est, sizeof(est));
    int n = snprintf(usr, sizeof(usr), "Evento: %s %s. Semilla %ld.", EV_DESC[ev], est, (long)random(100000));
    if (nFrases > 0) {
      n += snprintf(usr + n, sizeof(usr) - n, " No repitas ni imites estas frases:");
      for (int i = 0; i < nFrases && n < (int)sizeof(usr) - 60; i++) n += snprintf(usr + n, sizeof(usr) - n, " %s |", frasesRec[i]);
    }
    enLlamada = true;
    int e = llamarGemini(sis, false, usr, 200);
    enLlamada = false;
    registrarLlamada();
    ovr = -1;
    if (e == 0) { strncpy(frase, resp, sizeof(frase) - 1); frase[sizeof(frase) - 1] = 0; limpiarFrase(frase, 60); }
  }
  if (!frase[0]) strcpy(frase, EV_FRASES[ev][random(3)]);
  anotarFrase(frase);
  mostrarBurbuja(frase);
  if (EV_ANIMO[ev] >= 0) forzarAnimo(EV_ANIMO[ev], bubDur);
  if (ev != EV_DUERME) sndHabla();
}

// El robot contesta lo que le escribes en la web. Devuelve 0 si salio bien; "salida" lleva el texto o el error.
int hablarLibre(const char* texto, char* salida, int cap) {
  if (enLlamada) { snprintf(salida, cap, "Estoy ocupado, intenta otra vez."); return -9; }
  if (modo != M_PET || pagina != 0) { snprintf(salida, cap, "Estoy en otro modo, ponme en la carita."); return -8; }
  char sis[420], usr[500], est[140];
  snprintf(sis, sizeof(sis), "%s Te llamas %s. Eres un robotito mascota que vive en una pantallita. Contestas lo que te dice tu duena. "
           "Responde en maximo 2 frases cortas (110 caracteres en total) en espanol, sin apodos, sin emojis, sin acentos, sin comillas y sin markdown.",
           PERS_SYS[personalidad], nombre);
  estadoTexto(est, sizeof(est));
  snprintf(usr, sizeof(usr), "Tu duena te dice: %s. %s.", texto, est);
  forzarAnimo(A_PENSANDO, 30000UL);
  sndPensando();
  animoPrev = A_PENSANDO; animoIni = millis();
  dibujar();
  enLlamada = true;
  int e = llamarGemini(sis, false, usr, 250);
  enLlamada = false;
  registrarLlamada();
  ovr = -1;
  if (e != 0) { snprintf(salida, cap, "%s", textoError(e)); sndError(); return e; }
  strncpy(salida, resp, cap - 1); salida[cap - 1] = 0;
  limpiarFrase(salida, 110);
  anotarFrase(salida);
  ultHabla = millis();
  mostrarBurbuja(salida);
  forzarAnimo(A_FELIZ, bubDur);
  sndHabla();
  return 0;
}

// ======================= ESTADO DE ANIMO Y NECESIDADES =======================
unsigned long segundos = 0, tSeg = 0, ultCaricia = 0, proxCharla = 600000UL, ultGuardado = 0, ultMimo = 0;
unsigned long sndAnimoUlt[A_N];
bool oscuroCrudo = false, manoUsada = false;
unsigned long luzCambio = 0;

int animoBase() {
  if (durmiendo) return A_DORMIDO;
  if (frio) return A_FRIO;
  if (calor) return A_CALOR;
  if (energia < 15) return A_CANSADO;
  if (carino < 25) return A_TRISTE;
  return A_NEUTRO;
}
int animoActual() {
  unsigned long n = millis();
  if (ovr >= 0) {
    if (n < ovrHasta) return ovr;
    if (animoSig >= 0) { ovr = animoSig; ovrHasta = n + animoSigMs; animoSig = -1; return ovr; }
    ovr = -1;
  }
  return animoBase();
}
void alCambiarAnimo(int a) {                                      // sonidos al cambiar de cara
  unsigned long n = millis();
  if (modo != M_PET) return;
  if (sndAnimoUlt[a] && n - sndAnimoUlt[a] < 25000UL) return;
  sndAnimoUlt[a] = n;
  switch (a) {
    case A_FRIO: sndFrio(); break;
    case A_CALOR: sndCalor(); break;
    case A_TRISTE: sndTriste(); break;
    case A_BOSTEZO: sndBostezo(); break;
    case A_SORPRESA: sndSorpresa(); break;
    case A_DORMIDO: nuevaMelodia(); barrido(1200, 500, 500); break;
    default: break;
  }
}
void dormir() {
  durmiendo = true;
  guardarEstado();
  forzarAnimo(A_BOSTEZO, 1600);
  solicitarHabla(EV_DUERME, 300);
}
void despertarRobot() {
  durmiendo = false;
  forzarAnimo(A_SORPRESA, 700, A_BOSTEZO, 1600);
  solicitarHabla(EV_DESPIERTA, 2500);
}
void alAcariciar() {
  if (durmiendo) {                                                // dormido, solo hace "mmm"
    carino = min(100, carino + 2);
    forzarAnimo(A_AMOR, 1200);
    nuevaMelodia(); nota(700, 80); nota(900, 120);
    return;
  }
  carino = min(100, carino + 8);
  ultCaricia = millis();
  forzarAnimo(A_FELIZ, 2200);
  sndCaricia();
  solicitarHabla(EV_CARICIA, 1400);
}
void siguientePagina() {
  qrListo = false; paginaIni = millis();
  if (pagina == 0) pagina = 1;
  else if (pagina == 1) { pagina = 2; qrSub = 0; }
  else if (apActivo() && qrSub == 0) qrSub = 1;
  else { pagina = 0; abrirMenu(); }
}
void procesarMano() {
  unsigned long ahora = millis();
  if (leerNav()) { abrirMenu(); return; }                         // NAVEGAR = menu
  int ev = leerMano();
  if (ev == 1) manoUsada = false;
  if (ev == 2) {                                                  // OK toque corto
    if (pagina != 0) siguientePagina();
    else alAcariciar();
  }
  if (ev == 3 && pagina == 0 && ahora - manoDesde > 1500 && !durmiendo) solicitarHabla(EV_MIMOS, 500);
  if (manoEst && pagina == 0 && ahora - manoDesde >= 500) {       // OK mantenido = mimos
    forzarAnimo(A_AMOR, 300);
    ronroneo();
    if (ahora - ultMimo > 400) { ultMimo = ahora; carino = min(100, carino + 1); }
  }
}
void logica() {
  unsigned long ahora = millis();
  if (ahora - tSeg >= 1000) {                                     // necesidades, cada segundo
    tSeg = ahora; segundos++;
    if (durmiendo) { if (segundos % 12 == 0 && energia < 100) energia++; if (segundos % 300 == 0 && carino > 0) carino--; }
    else { if (segundos % 150 == 0 && energia > 0) energia--; if (segundos % 100 == 0 && carino > 0) carino--; }
  }
  bool o = oscuroCrudo;                                           // luz con histeresis
  if (luzFrac < 0.30f) o = true; else if (luzFrac > 0.45f) o = false;
  if (o != oscuroCrudo) { oscuroCrudo = o; luzCambio = ahora; }
  if (oscuroCrudo && !durmiendo && ahora - luzCambio > 2500) { dormir(); if (modo == M_MENU || modo == M_JUEGOS) modo = M_PET; }
  if (!oscuroCrudo && durmiendo && ahora - luzCambio > 700) despertarRobot();
  if (dhtOk) {                                                    // frio y calor
    if (!frio && tempC <= tFrio) { frio = true; solicitarHabla(EV_FRIO, 1200); }
    else if (frio && tempC >= tFrio + 2) frio = false;
    if (!calor && tempC >= tCalor) { calor = true; solicitarHabla(EV_CALOR, 1200); }
    else if (calor && tempC <= tCalor - 2) calor = false;
  }
  int a = animoActual();
  if (a != animoPrev) { alCambiarAnimo(a); animoPrev = a; animoIni = ahora; }
  if (evPend >= 0 && modo != M_PET && ahora > evCuando + 5000) evPend = -1;
  if (evPend >= 0 && ahora >= evCuando && !enLlamada && modo == M_PET) {           // algo que decir
    int ev = evPend;
    if (!durmiendo || ev == EV_DUERME) { evPend = -1; decirEvento(ev); }
    else if (ahora > evCuando + 5000) evPend = -1;
  }
  if (ahora > proxCharla) {                                       // de vez en cuando dice algo solito
    proxCharla = ahora + random(1500000L, 2700000L);
    if (!durmiendo && modo == M_PET && pagina == 0 && !bubAct) solicitarHabla((carino < 25 && ahora - ultCaricia > 600000UL) ? EV_SOLO : EV_CHARLA, 0);
  }
  if (bubAct && ahora - bubT0 > bubDur) bubAct = false;
  if (msgPend && modo == M_PET && pagina == 0 && !durmiendo && !enLlamada) {   // mensaje desde la web
    msgPend = false;
    mostrarBurbuja(msgWeb);
    forzarAnimo(A_SORPRESA, 700, A_FELIZ, bubDur);
    sndHabla();
    ultHabla = ahora;
  }
  if (pagina == 1 && ahora - paginaIni > 15000UL) { pagina = 0; qrListo = false; }
  if (pagina == 2 && ahora - paginaIni > 120000UL) { pagina = 0; qrListo = false; }
  if (ahora - ultGuardado > 300000UL) { ultGuardado = ahora; guardarEstado(); }
}

// ======================= PANTALLAS: informacion y QR =======================
void cabecera(const char* titulo, const char* derecha) {
  disp.setTextSize(1);
  disp.setTextColor(SSD1306_WHITE);
  disp.setCursor(4, 2); disp.print(titulo);
  int w = strlen(derecha) * 6;
  disp.setCursor(124 - w, 2); disp.print(derecha);
  disp.drawFastHLine(0, 11, 128, SSD1306_WHITE);
}
void centrado(const char* t, int y, int tam = 1) {
  disp.setTextSize(tam);
  disp.setCursor((128 - (int)strlen(t) * 6 * tam) / 2, y);
  disp.print(t);
}
void mensaje(const char* a, const char* b = "", const char* c = "") {
  disp.clearDisplay();
  disp.setTextColor(SSD1306_WHITE);
  centrado(a, 14); centrado(b, 28); centrado(c, 42);
  disp.display();
}
void barra(const char* et, int v, int y) {
  disp.setCursor(2, y); disp.print(et);
  disp.drawRect(52, y, 72, 8, SSD1306_WHITE);
  disp.fillRect(54, y + 2, (68 * v) / 100, 4, SSD1306_WHITE);
}
void dibujarInfo() {
  char hora[8] = "--:--";
  struct tm tm;
  if (getLocalTime(&tm, 0) && tm.tm_year >= 124) snprintf(hora, sizeof(hora), "%02d:%02d", tm.tm_hour, tm.tm_min);
  cabecera(nombre, hora);
  char a[28], b[28];
  if (dhtOk) snprintf(a, sizeof(a), "TEMP %dC  HUM %d%%", tempC, humedad); else snprintf(a, sizeof(a), "SIN SENSOR DHT11");
  snprintf(b, sizeof(b), "LUZ %d%%  %s", (int)(luzFrac * 100), oscuroCrudo ? "OSCURO" : "CLARO");
  disp.setTextSize(1);
  disp.setCursor(2, 14); disp.print(a);
  disp.setCursor(2, 24); disp.print(b);
  barra("CARINO", carino, 35);
  barra("ENERGIA", energia, 45);
  disp.drawFastHLine(0, 54, 128, SSD1306_WHITE);
  centrado("OK=SIG   NAV=MENU", 56);
}
void textoDer(int fila, const char* t) {                        // 10 letras por linea, a la derecha del QR
  char b[11]; strncpy(b, t, 10); b[10] = 0;
  disp.setCursor(68, 4 + fila * 9);
  disp.print(b);
}
void dibujarQRPantalla() {
  bool ap = apActivo();
  if (!ap && WiFi.status() != WL_CONNECTED) { centrado("SIN WIFI", 24); centrado("ENTRA A LA WEB DEL", 36); centrado("ROBOT POR SU RED", 46); return; }
  String ip = (ap ? WiFi.softAPIP() : WiFi.localIP()).toString();
  char url[40]; snprintf(url, sizeof(url), "http://%s", ip.c_str());
  char wifi[72]; snprintf(wifi, sizeof(wifi), "WIFI:T:WPA;S:%s;P:%s;;", AP_NOMBRE, AP_CLAVE);
  bool paraWifi = ap && qrSub == 0;
  if (!qrListo) { if (!qrCodificar(paraWifi ? wifi : url)) { centrado("TEXTO MUY LARGO", 28); return; } qrListo = true; }
  int lado = qrN * 2 + 6;
  dibujarQR(0, (64 - lado) / 2, 2, 3);
  disp.setTextSize(1);
  disp.setTextColor(SSD1306_WHITE);
  if (paraWifi) {
    textoDer(0, "1/2 WIFI"); textoDer(1, "RED:");
    textoDer(2, AP_NOMBRE); if (strlen(AP_NOMBRE) > 10) textoDer(3, AP_NOMBRE + 10);
    textoDer(4, "CLAVE:");
    textoDer(5, AP_CLAVE); if (strlen(AP_CLAVE) > 10) textoDer(6, AP_CLAVE + 10);
  } else {
    textoDer(0, ap ? "2/2 WEB" : "WEB"); textoDer(2, "ABRE:");
    int corte = 0, puntos = 0;
    for (int i = 0; ip[i]; i++) if (ip[i] == '.' && ++puntos == 2) { corte = i + 1; break; }
    char a[12], b[12];
    strncpy(a, ip.c_str(), corte); a[corte] = 0;
    strncpy(b, ip.c_str() + corte, 10); b[10] = 0;
    textoDer(3, a); textoDer(4, b);
    textoDer(6, "OK=SIG");
  }
}

// ======================= DIBUJO DE CADA CUADRO =======================
void dibujar() {
  unsigned long ahora = millis();
  disp.clearDisplay();
  disp.setTextColor(SSD1306_WHITE);
  if (pagina == 1) dibujarInfo();
  else if (pagina == 2) {
    dibujarQRPantalla();
  } else {
    bool burb = bubAct;
    bool habla = burb && (ahora - bubT0 < 1800);
    dibujarCara(animoPrev, ahora - animoIni, burb, habla);
    if (burb) {
      int paginas = (bubN + 1) / 2; if (paginas < 1) paginas = 1;
      int pag = (int)((ahora - bubT0) / 3200UL); if (pag >= paginas) pag = paginas - 1;
      disp.setTextSize(1);
      for (int k = 0; k < 2; k++) {
        int l = pag * 2 + k;
        if (l >= bubN) break;
        char t[24]; int n = bubIni[l + 1] - bubIni[l]; if (n > 21) n = 21;
        memcpy(t, bub + bubIni[l], n); t[n] = 0;
        while (n > 0 && t[n - 1] == ' ') t[--n] = 0;
        disp.setCursor((128 - n * 6) / 2, 45 + k * 10);
        disp.print(t);
      }
    }
    if (apActivo()) { disp.fillCircle(123, 4, 2, SSD1306_WHITE); }        // puntito = estoy en modo WiFi propio
  }
  disp.display();
}

// ======================= WIFI GUARDADO =======================
void leerRed(int s, char* ss, char* pw) {
  char k[4];
  ss[0] = 0; pw[0] = 0;
  prefs.begin("flanpet", true);
  snprintf(k, sizeof(k), "s%d", s); prefs.getString(k, ss, 33);
  snprintf(k, sizeof(k), "p%d", s); prefs.getString(k, pw, 65);
  prefs.end();
}
void guardarRed(const char* ss, const char* pw) {
  char a[34], b[66];
  int slot = -1;
  for (int s = 0; s < 3; s++) { leerRed(s, a, b); if (!strcmp(a, ss)) slot = s; }
  prefs.begin("flanpet", false);
  if (slot < 0) { slot = prefs.getInt("wn", 0) % 3; prefs.putInt("wn", (slot + 1) % 3); }
  char k[4];
  snprintf(k, sizeof(k), "s%d", slot); prefs.putString(k, ss);
  snprintf(k, sizeof(k), "p%d", slot); prefs.putString(k, pw);
  prefs.end();
}
void olvidarRed(int s) {
  char k[4];
  prefs.begin("flanpet", false);
  snprintf(k, sizeof(k), "s%d", s); prefs.remove(k);
  snprintf(k, sizeof(k), "p%d", s); prefs.remove(k);
  prefs.end();
}
bool intentarRed(const char* ss, const char* pw, unsigned long ms) {
  char nom[22]; strncpy(nom, ss, 21); nom[21] = 0;
  WiFi.disconnect();
  WiFi.mode(WIFI_STA);
  WiFi.begin(ss, pw[0] ? pw : nullptr);
  unsigned long ini = millis();
  while (WiFi.status() != WL_CONNECTED && millis() - ini < ms) {
    mensaje("CONECTANDO A:", nom, "ESPERA...");
    delay(300);
  }
  return WiFi.status() == WL_CONNECTED;
}
bool redVisible(int n, const char* ss) {
  if (n <= 0) return true;
  for (int i = 0; i < n; i++) if (!strcmp(WiFi.SSID(i).c_str(), ss)) return true;
  return false;
}
// Crea el WiFi propio del robot (para configurarlo desde el celular)
void iniciarAP() {
  WiFi.disconnect();
  WiFi.mode(WIFI_AP_STA);                                     // AP_STA para poder escanear redes desde la web
  WiFi.softAP(AP_NOMBRE, AP_CLAVE);
  delay(300);
  dns.start(53, "*", WiFi.softAPIP());
}
void conectarAuto() {
  WiFi.mode(WIFI_STA);
  WiFi.setAutoReconnect(true);
  mensaje("BUSCANDO REDES...");
  int n = WiFi.scanNetworks();
  char a[34], b[66];
  for (int s = 0; s < 3 && WiFi.status() != WL_CONNECTED; s++) {
    leerRed(s, a, b);
    if (a[0] && redVisible(n, a)) intentarRed(a, b, 12000);
  }
  if (WiFi.status() != WL_CONNECTED && WIFI_NOMBRE[0] && redVisible(n, WIFI_NOMBRE)) intentarRed(WIFI_NOMBRE, WIFI_CLAVE, 12000);
  WiFi.scanDelete();
  if (WiFi.status() == WL_CONNECTED) {
    apFallback = false;
    configTime(-5 * 3600, 0, "pool.ntp.org", "time.google.com");
    mensaje("WIFI LISTO", WiFi.localIP().toString().c_str());
    sndHola(); delay(900);
  } else {                                                    // sin internet: crea su WiFi para configurarlo
    apFallback = true;
    iniciarAP();
    mensaje("SIN INTERNET", "USA MI WIFI:", AP_NOMBRE);
    delay(1800);
    pagina = 2; qrSub = 0; paginaIni = millis();              // muestra el QR para conectarse
  }
}

// ======================= WEB =======================
String jEsc(const char* s) {
  String o;
  for (; *s; s++) {
    char c = *s;
    if (c == '"' || c == '\\') { o += '\\'; o += c; }
    else if ((unsigned char)c >= 32) o += c;
  }
  return o;
}
String asciiLimpio(const String& in) {
  String o; int n = in.length();
  for (int i = 0; i < n; i++) {
    unsigned char b = in[i];
    if (b < 0x80) { if (b >= 32) o += (char)b; else if (b == 10 || b == 13) o += ' '; continue; }
    unsigned cp = 0; int falta = 0;
    if ((b & 0xE0) == 0xC0) { cp = b & 0x1F; falta = 1; }
    else if ((b & 0xF0) == 0xE0) { cp = b & 0x0F; falta = 2; }
    else if ((b & 0xF8) == 0xF0) { cp = b & 0x07; falta = 3; }
    while (falta > 0 && i + 1 < n) { cp = (cp << 6) | ((unsigned char)in[++i] & 0x3F); falta--; }
    char c = aAscii(cp); if (c) o += c;
  }
  return o;
}

