  bool bien = n.length() >= 1 && n.length() <= 20 && c.length() >= 8 && c.length() <= 20;
  for (unsigned i = 0; bien && i < n.length(); i++) { unsigned char x = n[i]; if (x < 32 || x > 126 || strchr("\";,:\\", x)) bien = false; }
  for (unsigned i = 0; bien && i < c.length(); i++) { unsigned char x = c[i]; if (x < 33 || x > 126 || strchr("\";,:\\", x)) bien = false; }
  if (!bien) { servidor.send(200, "text/plain", "Nombre 1 a 20 letras, clave 8 a 20 sin espacios ni estos signos: \" ; , : \\"); return; }
  strcpy(AP_NOMBRE, n.c_str()); strcpy(AP_CLAVE, c.c_str());
  prefs.begin("flanpet", false);
  prefs.putString("apn", AP_NOMBRE); prefs.putString("apc", AP_CLAVE);
  prefs.end();
  if (apActivo()) { servidor.send(200, "text/plain", "Guardado. Reiniciando, vuelve a conectarte al WiFi nuevo."); delay(600); ESP.restart(); }
  else servidor.send(200, "text/plain", "Guardado.");
}
void webReiniciar() { servidor.send(200, "text/plain", "OK"); delay(500); ESP.restart(); }
void webReset() {
  prefs.begin("flanpet", false); prefs.clear(); prefs.end();
  servidor.send(200, "text/plain", "OK"); delay(500); ESP.restart();
}
void webNoEncontrada() {
  if (apActivo()) {                                          // portal: cualquier direccion abre el panel
    servidor.sendHeader("Location", String("http://") + WiFi.softAPIP().toString() + "/");
    servidor.send(302, "text/plain", "");
  } else servidor.send(404, "text/plain", "No existe");
}

void iniciarWeb() {
