  servidor.on("/update.html", HTTP_GET, []() { servidor.send_P(200, "text/html", PAGINA_UPDATE); });
  servidor.on("/api/estado", HTTP_GET, webEstado);
  servidor.on("/api/redes", HTTP_GET, webRedes);
  servidor.on("/api/ajustes", HTTP_POST, webAjustes);
  servidor.on("/api/accion", HTTP_POST, webAccion);
  servidor.on("/api/cara", HTTP_POST, webCara);
  servidor.on("/api/hablar", HTTP_POST, webHablar);
  servidor.on("/api/luz", HTTP_POST, webLuz);
  servidor.on("/api/key", HTTP_POST, webKey);
  servidor.on("/api/red", HTTP_POST, webRed);
  servidor.on("/api/olvidar", HTTP_POST, webOlvidar);
  servidor.on("/api/ap", HTTP_POST, webAP);
  servidor.on("/api/reiniciar", HTTP_POST, webReiniciar);
  servidor.on("/api/reset", HTTP_POST, webReset);
  servidor.on("/api/pc", HTTP_POST, webPC);
  servidor.on("/api/preguntar", HTTP_POST, webPreguntar);
  servidor.on("/api/mensaje", HTTP_POST, webMensaje);
  servidor.on("/api/notas", HTTP_GET, webNotas);
  servidor.on("/api/nota", HTTP_POST, webNotaGuardar);
  servidor.on("/api/registro", HTTP_GET, webRegistro);
  servidor.on("/update", HTTP_POST,
    []() {
      bool ok = !Update.hasError();
      servidor.sendHeader("Connection", "close");
      servidor.send(200, "text/plain", ok ? "OK" : "FAIL");
      if (ok) { delay(500); ESP.restart(); }
    },
    []() {
      HTTPUpload& up = servidor.upload();
      if (up.status == UPLOAD_FILE_START) {
        disp.clearDisplay();
        disp.setTextSize(1);
        disp.setTextColor(SSD1306_WHITE);
        disp.drawRect(4, 4, 120, 56, SSD1306_WHITE);
        disp.setCursor(18, 14); disp.println("ACTUALIZANDO...");
        disp.setCursor(14, 32); disp.println("NO APAGUES EL");
        disp.setCursor(14, 44); disp.println("ROBOT");
        disp.display();
        Update.begin(UPDATE_SIZE_UNKNOWN);
      } else if (up.status == UPLOAD_FILE_WRITE) {
        Update.write(up.buf, up.currentSize);
      } else if (up.status == UPLOAD_FILE_END) {
        Update.end(true);
      } else if (up.status == UPLOAD_FILE_ABORTED) {
        Update.end();
      }
    }
  );
  servidor.onNotFound(webNoEncontrada);
  servidor.begin();
  ArduinoOTA.setHostname("flan-pet");
  ArduinoOTA.begin();
}
void servicioWeb() {
  ArduinoOTA.handle();
  servidor.handleClient();
  if (apActivo()) dns.processNextRequest();
}

