  if (!disp.begin(SSD1306_SWITCHCAPVCC, 0x3C)) { for (;;) delay(1000); }
  pinMode(PIN_MANO, INPUT_PULLUP);
  pinMode(PIN_NAV, INPUT_PULLUP);
  pinMode(PIN_LUZ, INPUT);
#if USAR_POT
  pinMode(potPin, INPUT);
#endif
  cargarAjustes();
  aplicarPantalla();
  aplicarBrillo();
  iniciarBuzzer();
  cargarHighScores();
  randomSeed(esp_random());
  disp.clearDisplay(); disp.display();
  mensaje("FLAN PET", nombre, "DESPERTANDO...");
  delay(800);
  if (redModo == 1) {
    iniciarAP();
    mensaje("MI WIFI:", AP_NOMBRE, AP_CLAVE);
    delay(1500);
  } else conectarAuto();
  iniciarWeb();
  servicioLuz();
  for (int i = 0; i < 8; i++) { servicioLuz(); delay(30); }
  oscuroCrudo = luzFrac < 0.30f;
  animoPrev = animoBase(); animoIni = millis();
  if (pagina == 0) { forzarAnimo(A_SORPRESA, 700, A_FELIZ, 1500); sndHola(); solicitarHabla(EV_HOLA, 1800); }
  tSeg = millis(); ultGuardado = millis();
}

void loop() {
  servicioWeb();
  servicioSonido();
  if (modo != M_JUEGO) { servicioDHT(); revisarTemp(); }
  servicioLuz();
  logica();
  switch (modo) {
    case M_PET: {
      procesarMano();
      static unsigned long ultCuadro = 0;
      if (modo == M_PET && millis() - ultCuadro >= 40) { ultCuadro = millis(); dibujar(); }
      break;
    }
    case M_MENU: tickMenu(); break;
    case M_JUEGOS: tickMenuJuegos(); break;
    case M_JUEGO: tickJuego(); break;
    default: tickIA(); break;
  }
}
