unsigned long juegoUlt = 0, tFinJuego = 0;

bool juegoTerminado() {
  switch (juegoActual) {
    case 0: return finDino;
    case 1: return finFlappy;
    case 2: return finPong;
    case 3: return finSpace;
    case 4: return finArkanoid;
    case 5: return finSnake;
