// ---------- un cuadro de cada juego ----------
void juegoDino() {
  int sensor = digitalRead(PIN_MANO);
  unsigned long tAct = millis();
  static bool libreDino = true;
  static unsigned long tManoDino = 0;

  if (sensor == LOW) {
    if (libreDino) { tManoDino = tAct; libreDino = false; }
    if ((tAct - tManoDino > 250) && !enSaltoDino) { estaAgachado = true; dinoAltura = 6; dinoY = 47; }
  } else {
    if (!libreDino) {
      if ((tAct - tManoDino) < 250 && !estaAgachado && !enSaltoDino) { enSaltoDino = true; velocidadSaltoDino = -9; emitirSonido(550, 70); }
    }
    if (estaAgachado) { estaAgachado = false; dinoAltura = 10; dinoY = 43; }
    libreDino = true;
  }

  if (enSaltoDino) {
    dinoY += velocidadSaltoDino;
    velocidadSaltoDino += 1;
    if (dinoY >= 43) { dinoY = 43; enSaltoDino = false; }
  }

  obstaculoX -= (int)velocidadObstaculoDino;
  if (obstaculoX < -15) {
    obstaculoX = 128; ptoDino += 10;
    if (ptoDino >= siguienteModo) { modoNocheDino = !modoNocheDino; siguienteModo += 100; emitirSonido(1318, 120); }
    else emitirSonido(1200, 40);
    tipoObstaculo = random(0, 3);
    if (velocidadObstaculoDino < 6.5) velocidadObstaculoDino += 0.15;
  }

  if (!enSaltoDino && !estaAgachado) {
    animDino++;
    if (animDino > 4) { frameDino = !frameDino; animDino = 0; }
  }

  if (tipoObstaculo == 0 && obstaculoX >= 10 && obstaculoX <= 18 && dinoY >= 38) { finDino = true; emitirSonido(200, 150); }
  if (tipoObstaculo == 1 && obstaculoX >= 10 && obstaculoX <= 20 && dinoY >= 38) { finDino = true; emitirSonido(200, 150); }
  if (tipoObstaculo == 2 && obstaculoX >= 10 && obstaculoX <= 18 && !estaAgachado) { finDino = true; emitirSonido(200, 150); }

  disp.clearDisplay();
  if (modoNocheDino != dinoInv) {
    dinoInv = modoNocheDino;
    disp.invertDisplay(dinoInv != pantInvertida);
  }
  disp.drawLine(0, 52, 128, 52, SSD1306_WHITE);
  disp.fillRect(10, dinoY, 10, dinoAltura, SSD1306_WHITE);
  disp.fillRect(16, dinoY - 4, 6, 6, SSD1306_WHITE);
  if (!enSaltoDino && !estaAgachado) {
    if (frameDino) { disp.fillRect(11, dinoY + 10, 2, 4, SSD1306_WHITE); disp.fillRect(16, dinoY + 10, 2, 2, SSD1306_WHITE); }
    else { disp.fillRect(11, dinoY + 10, 2, 2, SSD1306_WHITE); disp.fillRect(16, dinoY + 10, 2, 4, SSD1306_WHITE); }
  }
  if (tipoObstaculo == 0) disp.fillRect(obstaculoX, 39, 6, 13, SSD1306_WHITE);
  else if (tipoObstaculo == 1) { disp.fillRect(obstaculoX, 39, 5, 13, SSD1306_WHITE); disp.fillRect(obstaculoX + 6, 42, 5, 10, SSD1306_WHITE); }
  else disp.fillRect(obstaculoX, 32, 8, 4, SSD1306_WHITE);
  disp.setTextSize(1); disp.setTextColor(SSD1306_WHITE);
  disp.setCursor(64, 4); disp.print("PTS:"); disp.print(ptoDino);
  disp.setCursor(64, 14); disp.print("HI:"); disp.print(highScores[0]);
  disp.display();
}

void juegoFlappy() {
  static bool antFlappy = HIGH;
  bool actFlappy = digitalRead(PIN_MANO);
  if (antFlappy == HIGH && actFlappy == LOW) { velFlappy = -4.2; emitirSonido(600, 50); }
  antFlappy = actFlappy;

  velFlappy += gravedadFlappy;
  flappyY += velFlappy;
  tuboX -= 3;
  if (tuboX < -12) { tuboX = 128; tuboTop = random(10, 32); ptoFlappy += 10; emitirSonido(1100, 40); }
  if (flappyY > 58 || flappyY < 0 || (tuboX >= 12 && tuboX <= 28 && (flappyY < tuboTop || flappyY > (tuboTop + huecoFlappy)))) { finFlappy = true; emitirSonido(180, 200); }

  disp.clearDisplay();
  disp.fillRect(20, (int)flappyY, 6, 5, SSD1306_WHITE);
  disp.fillRect(tuboX, 0, 10, tuboTop, SSD1306_WHITE);
  disp.fillRect(tuboX, tuboTop + huecoFlappy, 10, 64 - (tuboTop + huecoFlappy), SSD1306_WHITE);
  disp.setTextSize(1); disp.setTextColor(SSD1306_WHITE);
  disp.setCursor(70, 4); disp.print("PTS:"); disp.print(ptoFlappy);
  disp.display();
}

void juegoPong() {
  if (digitalRead(PIN_MANO) == LOW) palaPongY -= 3; else palaPongY += 3;
  if (palaPongY < 0) palaPongY = 0;
  if (palaPongY > 48) palaPongY = 48;

  bolaPongX += velBolaX;
  bolaPongY += velBolaY;
  if (bolaPongY <= 0 || bolaPongY >= 62) { velBolaY = -velBolaY; emitirSonido(400, 20); }
  if (bolaPongX >= 124) { velBolaX = -velBolaX; emitirSonido(400, 20); }
  if (bolaPongX <= 8 && bolaPongY >= palaPongY && bolaPongY <= palaPongY + 16) { velBolaX = -velBolaX; ptoPong += 10; emitirSonido(800, 30); }
  if (bolaPongX < 0) { finPong = true; emitirSonido(150, 300); }

  disp.clearDisplay();
  disp.fillRect(4, palaPongY, 4, 16, SSD1306_WHITE);
  disp.fillRect(124, 0, 4, 64, SSD1306_WHITE);
  disp.fillCircle((int)bolaPongX, (int)bolaPongY, 2, SSD1306_WHITE);
  disp.setTextSize(1); disp.setTextColor(SSD1306_WHITE);
  disp.setCursor(70, 4); disp.print("PTS:"); disp.print(ptoPong);
  disp.display();
}

void juegoSpace() {
  static bool antSpace = HIGH;
  bool actSpace = digitalRead(PIN_MANO);
  if (antSpace == HIGH && actSpace == LOW && balaSpaceY < 0) { balaSpaceX = naveSpaceX + 3; balaSpaceY = 50; emitirSonido(900, 30); }
  antSpace = actSpace;

  static int dirNave = 1;
  naveSpaceX += dirNave;
  if (naveSpaceX > 110 || naveSpaceX < 5) dirNave = -dirNave;

  alienX += dirAlien;
  if (alienX > 90 || alienX < 5) { dirAlien = -dirAlien; alienY += 4; }

  if (balaSpaceY >= 0) {
    balaSpaceY -= 5;
    if (balaSpaceY >= alienY && balaSpaceY <= alienY + 6 && balaSpaceX >= alienX && balaSpaceX <= alienX + 12) {
      ptoSpace += 20; balaSpaceY = -1; alienX = random(10, 60); emitirSonido(1200, 50);
    }
  }
  if (alienY >= 45) { finSpace = true; emitirSonido(150, 300); }

  disp.clearDisplay();
  disp.fillRect(naveSpaceX, 56, 8, 4, SSD1306_WHITE);
  if (balaSpaceY >= 0) disp.drawPixel(balaSpaceX, balaSpaceY, SSD1306_WHITE);
  disp.fillRect(alienX, alienY, 12, 6, SSD1306_WHITE);
  disp.setTextSize(1); disp.setTextColor(SSD1306_WHITE);
  disp.setCursor(70, 4); disp.print("PTS:"); disp.print(ptoSpace);
  disp.display();
}

void juegoArkanoid() {
  if (digitalRead(PIN_MANO) == LOW) palaArkanoidX += 3; else palaArkanoidX -= 3;
  if (palaArkanoidX < 0) palaArkanoidX = 0;
  if (palaArkanoidX > 104) palaArkanoidX = 104;

  bolaArkanoidX += velArkanoidX;
  bolaArkanoidY += velArkanoidY;
  if (bolaArkanoidX <= 0 || bolaArkanoidX >= 126) { velArkanoidX = -velArkanoidX; emitirSonido(400, 20); }
  if (bolaArkanoidY <= 0) { velArkanoidY = -velArkanoidY; emitirSonido(400, 20); }
  if (bolaArkanoidY >= 58 && bolaArkanoidX >= palaArkanoidX && bolaArkanoidX <= palaArkanoidX + 24) { velArkanoidY = -velArkanoidY; emitirSonido(700, 30); }
  if (bolaArkanoidY > 64) { finArkanoid = true; emitirSonido(150, 300); }

  int bx = (int)(bolaArkanoidX / 16);
  int by = (int)(bolaArkanoidY / 8);
  if (by >= 0 && by < 3 && bx >= 0 && bx < 8 && bloques[by][bx]) {
    bloques[by][bx] = false; velArkanoidY = -velArkanoidY; ptoArkanoid += 15; emitirSonido(1000, 40);
  }

  disp.clearDisplay();
  disp.fillRect(palaArkanoidX, 60, 24, 3, SSD1306_WHITE);
  disp.fillCircle((int)bolaArkanoidX, (int)bolaArkanoidY, 2, SSD1306_WHITE);
  for (int f = 0; f < 3; f++) for (int c = 0; c < 8; c++) if (bloques[f][c]) disp.fillRect(c * 16 + 1, f * 8 + 2, 14, 6, SSD1306_WHITE);
  disp.setTextSize(1); disp.setTextColor(SSD1306_WHITE);
  disp.setCursor(70, 54); disp.print("PTS:"); disp.print(ptoArkanoid);
  disp.display();
}

void juegoSnake() {
  static bool antSnake = HIGH;
  bool actSnake = digitalRead(PIN_MANO);
  if (antSnake == HIGH && actSnake == LOW) {
    if (dirSnakeX == 4) { dirSnakeX = 0; dirSnakeY = 4; }
    else if (dirSnakeY == 4) { dirSnakeX = -4; dirSnakeY = 0; }
    else if (dirSnakeX == -4) { dirSnakeX = 0; dirSnakeY = -4; }
    else if (dirSnakeY == -4) { dirSnakeX = 4; dirSnakeY = 0; }
    emitirSonido(500, 20);
  }
  antSnake = actSnake;

  if (millis() - tiempoUltimoMovSnake > 140) {
    tiempoUltimoMovSnake = millis();
    for (int i = longitudSnake - 1; i > 0; i--) { snakeX[i] = snakeX[i - 1]; snakeY[i] = snakeY[i - 1]; }
    snakeX[0] += dirSnakeX;
    snakeY[0] += dirSnakeY;
    if (snakeX[0] < 0 || snakeX[0] >= 128 || snakeY[0] < 0 || snakeY[0] >= 64) { finSnake = true; emitirSonido(150, 300); }
    for (int i = 1; i < longitudSnake; i++) if (snakeX[0] == snakeX[i] && snakeY[0] == snakeY[i]) { finSnake = true; emitirSonido(150, 300); }
    if (abs(snakeX[0] - comidaX) < 5 && abs(snakeY[0] - comidaY) < 5) {
      longitudSnake++;
      if (longitudSnake > 48) longitudSnake = 48;
      ptoSnake += 10;
      emitirSonido(1400, 50);
      comidaX = random(10, 118);
      comidaY = random(10, 54);
