// ---------- se llama en cada vuelta cuando estas jugando ----------
void tickJuego() {
  unsigned long ahora = millis();
  static bool pausa = false;
  if (juegoEsperaSoltar) {                                   // espera a que sueltes OK
    if (digitalRead(PIN_MANO) == LOW) return;
    juegoEsperaSoltar = false;
    resetMano();
  }
  if (juegoTerminado()) {
    if (tFinJuego == 0) {
      tFinJuego = ahora; finEspera = true;
      guardarHighScore(juegoActual, juegoPuntos());
      dibujarFinJuego();
    }
    if (finEspera) {                                         // no se sale hasta soltar la mano
      if (ahora - tFinJuego < 700 || digitalRead(PIN_MANO) == LOW) return;
      finEspera = false; gestoUsado = false; resetMano();
    }
    int g = gesto();
    if (g == 2) { emitirSonido(900, 100); iniciarJuego(juegoActual); }
    else if (g == 1) { emitirSonido(800, 80); salirJuego(); }
    return;
  }
  if (pausa) {                                               // en pausa: OK sigue, NAVEGAR sale
    if (leerNav()) { pausa = false; emitirSonido(800, 80); salirJuego(); return; }
    if (leerMano() == 1) { pausa = false; juegoEsperaSoltar = true; emitirSonido(1000, 60); }
    return;
  }
  if (leerNav()) {                                           // NAVEGAR = pausa
    pausa = true;
    nuevaMelodia();
    disp.invertDisplay(pantInvertida);
    disp.clearDisplay();
    disp.setTextColor(SSD1306_WHITE);
    centrado("PAUSA", 8, 2);
    centrado("OK  = SEGUIR", 34);
    centrado("NAV = SALIR", 46);
    disp.display();
    return;
  }
  if (ahora - juegoUlt < 30) return;
  juegoUlt = ahora;
  switch (juegoActual) {
    case 0: juegoDino(); break;
    case 1: juegoFlappy(); break;
    case 2: juegoPong(); break;
    case 3: juegoSpace(); break;
    case 4: juegoArkanoid(); break;
    case 5: juegoSnake(); break;
    default: juegoClimb(); break;
  }
}
