// Posicion del potenciometro (0..n-1), promediada y con histeresis
int leerPot(int n) {
  static float suave = -1;
  int anterior = potIdx;
  long suma = 0;
  for (int i = 0; i < 16; i++) suma += analogRead(potPin);
  float v = suma / 16.0f;
  potCrudo = (int)v;
  if (suave < 0) suave = v; else suave = suave * 0.7f + v * 0.3f;
  const float MINIMO = 150, MAXIMO = 3900;
  float x = (suave - MINIMO) / (MAXIMO - MINIMO);
  if (x < 0) x = 0;
  if (x > 0.999f) x = 0.999f;
  float pos = x * n;
  if (pos > potIdx + 1.3f || pos < potIdx - 0.3f) potIdx = (int)pos;
  if (potIdx >= n) potIdx = n - 1;
  if (potIdx < 0) potIdx = 0;
  if (potIdx != anterior) despertar();
  return potIdx;
}
