//<<PURE
const char* ep;
bool eErr = false;
double ansV = 0;

void saltaEsp() { while (*ep == ' ') ep++; }
double pExpr();

double pPrimary() {
  saltaEsp();
  if (*ep == '(') {
    ep++;
    double v = pExpr();
    saltaEsp();
    if (*ep == ')') ep++; else eErr = true;
    return v;
  }
  if ((*ep >= '0' && *ep <= '9') || *ep == '.') {
    double v = 0; bool punto = false; double dec = 1; int digs = 0;
    while ((*ep >= '0' && *ep <= '9') || *ep == '.') {
      if (*ep == '.') { if (punto) { eErr = true; return 0; } punto = true; }
      else {
        digs++;
        if (!punto) v = v * 10 + (*ep - '0');
        else { dec /= 10; v += (*ep - '0') * dec; }
      }
      ep++;
    }
    if (digs == 0) { eErr = true; return 0; }
    return v;
  }
  if (*ep >= 'A' && *ep <= 'Z') {
    char nom[8]; int k = 0;
    while (*ep >= 'A' && *ep <= 'Z') { if (k < 7) nom[k++] = *ep; ep++; }
    nom[k] = 0;
    if (!strcmp(nom, "PI")) return M_PI;
    if (!strcmp(nom, "E")) return M_E;
    if (!strcmp(nom, "ANS")) return ansV;
    saltaEsp();
    if (*ep != '(') { eErr = true; return 0; }
    ep++;
    double a = pExpr();
    saltaEsp();
    if (*ep == ')') ep++; else eErr = true;
    if (!strcmp(nom, "SQRT")) { if (a < 0) { eErr = true; return 0; } return sqrt(a); }
    if (!strcmp(nom, "SIN")) return sin(a * M_PI / 180.0);
    if (!strcmp(nom, "COS")) return cos(a * M_PI / 180.0);
    if (!strcmp(nom, "TAN")) return tan(a * M_PI / 180.0);
    if (!strcmp(nom, "LOG")) { if (a <= 0) { eErr = true; return 0; } return log10(a); }
    if (!strcmp(nom, "LN"))  { if (a <= 0) { eErr = true; return 0; } return log(a); }
    if (!strcmp(nom, "ABS")) return fabs(a);
    eErr = true; return 0;
  }
  eErr = true;
  return 0;
}

double pPost() {
  double v = pPrimary();
  saltaEsp();
  while (*ep == '!') {
    ep++;
    if (v < 0 || v > 170 || v != floor(v)) { eErr = true; return 0; }
    double f = 1;
    for (int i = 2; i <= (int)v; i++) f *= i;
    v = f;
    saltaEsp();
  }
  return v;
}

double pUn();
double pPow() {
  double b = pPost();
  saltaEsp();
  if (*ep == '^') {
    ep++;
    double e = pUn();
    if (b < 0 && e != floor(e)) { eErr = true; return 0; }
    return pow(b, e);
  }
  return b;
}

double pUn() {
  saltaEsp();
  if (*ep == '-') { ep++; return -pUn(); }
  if (*ep == '+') { ep++; return pUn(); }
  return pPow();
}

double pTerm() {
  double v = pUn();
  for (;;) {
    saltaEsp();
    char c = *ep;
    if (c == 'x' || c == '*') { ep++; v *= pUn(); }
    else if (c == '/') {
      ep++;
      double d = pUn();
      if (d == 0) { eErr = true; return 0; }
      v /= d;
    } else break;
  }
  return v;
}

double pExpr() {
  double v = pTerm();
  for (;;) {
    saltaEsp();
    char c = *ep;
    if (c == '+') { ep++; v += pTerm(); }
    else if (c == '-') { ep++; v -= pTerm(); }
    else break;
  }
  return v;
}

bool evaluar(const char* s, double& out) {
  ep = s; eErr = false;
  double v = pExpr();
  saltaEsp();
  if (*ep || eErr || isnan(v) || isinf(v)) return false;
  out = v;
  return true;
}

void fmtNum(double v, char* o, size_t n) {
  if (fabs(v) < 1e-12) v = 0.0;
  if (v == floor(v) && fabs(v) < 1e9) snprintf(o, n, "%.0f", v);
  else snprintf(o, n, "%.7g", v);
}

long mcdL(long a, long b) {
  if (a < 0) a = -a;
  if (b < 0) b = -b;
  while (b) { long t = a % b; a = b; b = t; }
  return a;
}

void factoresPrimos(long n, char* o, size_t cap) {
  o[0] = 0;
  if (n < 2) { snprintf(o, cap, "%ld", n); return; }
  size_t len = 0; bool primero = true;
  for (long p = 2; p * p <= n; p++) {
    int e = 0;
    while (n % p == 0) { n /= p; e++; }
    if (e && len < cap) {
      len += snprintf(o + len, cap - len, primero ? "%ld" : "x%ld", p);
      if (e > 1 && len < cap) len += snprintf(o + len, cap - len, "^%d", e);
      primero = false;
    }
  }
  if (n > 1 && len < cap) snprintf(o + len, cap - len, primero ? "%ld" : "x%ld", n);
}
