const char* AYUDA_LISTA = USAR_POT ? "GIRA=MOVER OK=ELEGIR" : "NAV=SIG OK=ELEGIR";

int elegirLista(const char* titulo, const char* const* items, int n, bool wifi, int inicial = 0) {
  int sel = inicial, top = 0;
  resetGesto();
#if USAR_POT
  sel = leerPot(n);
#endif
  while (true) {
    iaFondo();
    if (wifi && webNueva) return -1;                      // llego algo desde la web (solo en el menu principal)
    int g = gesto();
    int antes = sel;
#if USAR_POT
    sel = leerPot(n);
    if (g == 1 || g == 2) { sonidoOk(); return sel; }
#else
    if (g == 1) sel = (sel + 1) % n;
    if (g == 2) { sonidoOk(); return sel; }
#endif
    if (sel != antes) sonidoTick();
    if (sel < top) top = sel;
    if (sel >= top + 5) top = sel - 4;
    disp.clearDisplay();
    char der[12];
    if (wifi && redModo == 1) snprintf(der, sizeof(der), "PROPIA %d", (int)WiFi.softAPgetStationNum());
    else if (wifi) snprintf(der, sizeof(der), "%s", WiFi.status() == WL_CONNECTED ? "WIFI OK" : "SIN WIFI");
    else snprintf(der, sizeof(der), "%d/%d", sel + 1, n);
    cabecera(titulo, der);
    for (int i = 0; i < 5 && top + i < n; i++) {
      int y = 14 + i * 8;
      int idx = top + i;
      if (idx == sel) { disp.fillRect(0, y - 1, 124, 9, SSD1306_WHITE); disp.setTextColor(SSD1306_BLACK); }
      else disp.setTextColor(SSD1306_WHITE);
      disp.setCursor(3, y);
      char fila[21]; strncpy(fila, items[idx], 20); fila[20] = 0;
      disp.print(fila);
    }
    if (n > 5) {                                          // barra de desplazamiento
      disp.drawFastVLine(126, 13, 40, SSD1306_WHITE);
      int h = 40 * 5 / n; if (h < 4) h = 4;
      int yb = 13 + (40 - h) * top / (n - 5);
      disp.fillRect(125, yb, 3, h, SSD1306_WHITE);
    }
    pie(AYUDA_LISTA);
    disp.display();
    delay(20);
  }
}

