char L[14][22];
int nL = 0;
void Lc() { nL = 0; }
void La(const char* fmt, ...) {
  if (nL >= 14) return;
  va_list ap; va_start(ap, fmt);
  vsnprintf(L[nL], 22, fmt, ap);
  va_end(ap);
  nL++;
}

// Muestra nL lineas por paginas de 5. Toque = siguiente pagina (o salir en la ultima), mantener = salir
void visor(const char* titulo) {
  int paginas = (nL + 4) / 5; if (paginas < 1) paginas = 1;
  int pag = 0;
  resetGesto();
  while (true) {
    iaFondo();
    int g = gesto();
    if (g == 2) { sonidoOk(); return; }
    if (g == 1) {
      sonidoTick();
      if (pag + 1 >= paginas) return;
      pag++;
    }
    disp.clearDisplay();
    char der[12]; snprintf(der, sizeof(der), "%d/%d", pag + 1, paginas);
    cabecera(titulo, der);
    disp.setTextColor(SSD1306_WHITE);
    for (int l = 0; l < 5 && pag * 5 + l < nL; l++) {
      disp.setCursor(2, 14 + l * 8);
      disp.print(L[pag * 5 + l]);
    }
    pie(pag + 1 >= paginas ? "NAV U OK=SALIR" : "NAV=SIG OK=SALIR");
    disp.display();
    delay(30);
  }
}

// ======================= SLIDER (brillo, volumen) =======================
// Con el potenciometro: gira = cambia, OK = guarda, NAV = cancela.
// Sin potenciometro: NAV = sube, OK = guarda.
bool elegirValor(const char* titulo, int& valor, int minimo, void (*aplicar)(), bool sonar) {
  int original = valor;
  int n = (100 - minimo) / 10 + 1;
  resetGesto();
  int base = leerPot(n);
  bool movido = false;
  while (true) {
    iaFondo();
    int g = gesto();
    int antes = valor;
#if USAR_POT
    int p = leerPot(n);
    if (p != base) movido = true;
    if (movido) valor = minimo + p * 10;
    if (g == 1) { sonidoOk(); return true; }
    if (g == 2) { valor = original; aplicar(); return false; }
#else
    (void)base; (void)movido;
    if (g == 1) { valor += 10; if (valor > 100) valor = minimo; }
    if (g == 2) { sonidoOk(); return true; }
#endif
    if (valor != antes) { aplicar(); if (sonar) pip(1500, 30); }
    disp.clearDisplay();
    cabecera(titulo, "");
    char t[8]; snprintf(t, sizeof(t), "%d%%", valor);
    disp.setTextColor(SSD1306_WHITE);
    centrado(t, 18, 2);
    disp.drawRect(10, 40, 108, 8, SSD1306_WHITE);
    disp.fillRect(12, 42, (int)(104L * valor / 100), 4, SSD1306_WHITE);
    pie(USAR_POT ? "OK=GUARDAR NAV=CANCELAR" : "NAV=SUBIR OK=GUARDAR");
    disp.display();
    delay(20);
  }
}
