// Pide un numero (o una expresion como 3/4 o SQRT(2)). false = el usuario salio
bool pedirNum(const char* etiqueta, double& v) {
  char buf[48]; buf[0] = 0;
  while (true) {
    if (!tecladoGen(1, etiqueta, buf, sizeof(buf), 1)) return false;
    if (evaluar(buf, v)) return true;
    sonidoError();
    mensaje("EXPRESION INVALIDA", "REVISA PARENTESIS", "Y DIVISIONES");
    delay(1300);
  }
}

void herrExpresion() {
  char buf[48]; buf[0] = 0;
  while (true) {
    if (!tecladoGen(1, "CALCULA (ANS=ULTIMO)", buf, sizeof(buf), 1)) return;
    double v;
    if (!evaluar(buf, v)) {
      sonidoError();
      mensaje("EXPRESION INVALIDA", "REVISA PARENTESIS", "Y DIVISIONES");
      delay(1300);
      continue;
    }
    char r[24]; fmtNum(v, r, sizeof(r));
    ansV = v;
