void herrCuadratica() {
  double a, b, c;
  if (!pedirNum("ax2+bx+c=0  a =", a)) return;
  if (!pedirNum("b =", b)) return;
  if (!pedirNum("c =", c)) return;
  Lc();
  char t1[20], t2[20];
  if (a == 0) {
    if (b == 0) La(c == 0 ? "INFINITAS SOLUCIONES" : "SIN SOLUCION");
    else { fmtNum(-c / b, t1, 20); La("ES LINEAL"); La("x = %s", t1); }
  } else {
    double d = b * b - 4 * a * c;
    fmtNum(d, t1, 20);
    La("DISC = %s", t1);
    if (d > 0) {
      fmtNum((-b + sqrt(d)) / (2 * a), t1, 20);
      fmtNum((-b - sqrt(d)) / (2 * a), t2, 20);
      La("x1 = %s", t1);
      La("x2 = %s", t2);
    } else if (d == 0) {
      fmtNum(-b / (2 * a), t1, 20);
      La("UNA SOLUCION");
      La("x = %s", t1);
    } else {
      fmtNum(-b / (2 * a), t1, 20);
      fmtNum(sqrt(-d) / (2 * fabs(a)), t2, 20);
      La("SIN SOLUCION REAL");
      La("COMPLEJAS:");
      La("%s +- %si", t1, t2);
    }
  }
  visor("2o GRADO");
}

void herrSistema() {
  double a1, b1, c1, a2, b2, c2;
  if (!pedirNum("a1x+b1y=c1  a1 =", a1)) return;
  if (!pedirNum("b1 =", b1)) return;
  if (!pedirNum("c1 =", c1)) return;
  if (!pedirNum("a2x+b2y=c2  a2 =", a2)) return;
  if (!pedirNum("b2 =", b2)) return;
  if (!pedirNum("c2 =", c2)) return;
  Lc();
  double det = a1 * b2 - a2 * b1;
  if (det == 0) { La("SIN SOLUCION UNICA"); La("(RECTAS PARALELAS"); La("O IGUALES)"); }
  else {
    char sx[20], sy[20];
    fmtNum((c1 * b2 - c2 * b1) / det, sx, 20);
    fmtNum((a1 * c2 - a2 * c1) / det, sy, 20);
    La("x = %s", sx);
    La("y = %s", sy);
  }
  visor("SISTEMA 2x2");
}

void herrGeometria() {
  const char* it[] = {"CIRCULO", "RECTANGULO", "TRIANGULO", "ESFERA", "CILINDRO", "< VOLVER"};
  int o = elegirLista("GEOMETRIA", it, 6, false);
  if (o == 5) return;
  double a = 0, b = 0, v1 = 0, v2 = 0;
  char s1[20], s2[20];
