  if (o == 0) {
    if (!pedirNum("RADIO", a)) return;
    fmtNum(M_PI * a * a, s1, 20); fmtNum(2 * M_PI * a, s2, 20);
    La("AREA = %s", s1); La("PERIM = %s", s2);
  } else if (o == 1) {
    if (!pedirNum("BASE", a)) return;
    if (!pedirNum("ALTO", b)) return;
    fmtNum(a * b, s1, 20); fmtNum(2 * (a + b), s2, 20);
