    if (!pedirNum("ALTURA", b)) return;
    fmtNum(a * b / 2, s1, 20);
    La("AREA = %s", s1);
  } else if (o == 3) {
    if (!pedirNum("RADIO", a)) return;
    fmtNum(4.0 / 3.0 * M_PI * a * a * a, s1, 20); fmtNum(4 * M_PI * a * a, s2, 20);
    La("VOL = %s", s1); La("AREA = %s", s2);
  } else {
    if (!pedirNum("RADIO", a)) return;
    if (!pedirNum("ALTURA", b)) return;
    fmtNum(M_PI * a * a * b, s1, 20); fmtNum(2 * M_PI * a * (a + b), s2, 20);
    La("VOL = %s", s1); La("AREA = %s", s2);
  }
  (void)v1; (void)v2;
  visor("GEOMETRIA");
}

void herrEstadistica() {
  double cuantos;
  if (!pedirNum("CUANTOS DATOS (1-10)", cuantos)) return;
  int n = (int)cuantos;
  if (n < 1 || n > 10) { sonidoError(); mensaje("DE 1 A 10 DATOS"); delay(1200); return; }
  double d[10];
  for (int i = 0; i < n; i++) {
    char et[24]; snprintf(et, sizeof(et), "DATO %d DE %d", i + 1, n);
    if (!pedirNum(et, d[i])) return;
  }
  double s[10]; double suma = 0;
  for (int i = 0; i < n; i++) { s[i] = d[i]; suma += d[i]; }
  for (int i = 0; i < n; i++) for (int j = i + 1; j < n; j++) if (s[j] < s[i]) { double t = s[i]; s[i] = s[j]; s[j] = t; }
  double med = (n % 2) ? s[n / 2] : (s[n / 2 - 1] + s[n / 2]) / 2;
  char a[20];
  Lc();
  La("DATOS = %d", n);
  fmtNum(suma, a, 20); La("SUMA = %s", a);
  fmtNum(suma / n, a, 20); La("PROMEDIO = %s", a);
  fmtNum(med, a, 20); La("MEDIANA = %s", a);
  fmtNum(s[0], a, 20); La("MIN = %s", a);
  fmtNum(s[n - 1], a, 20); La("MAX = %s", a);
  visor("ESTADISTICA");
}

void herrConversor() {
  const char* it[] = {"C a F", "F a C", "km a millas", "millas a km", "kg a libras", "libras a kg",
                      "m a pies", "pies a m", "cm a pulgadas", "pulgadas a cm", "km/h a m/s", "m/s a km/h", "< VOLVER"};
