  if (o == 12) return;
  double v;
  if (!pedirNum(it[o], v)) return;
  double r = 0;
  switch (o) {
    case 0: r = v * 9.0 / 5.0 + 32; break;
    case 1: r = (v - 32) * 5.0 / 9.0; break;
    case 2: r = v * 0.621371; break;
    case 3: r = v / 0.621371; break;
    case 4: r = v * 2.204623; break;
    case 5: r = v / 2.204623; break;
    case 6: r = v * 3.280840; break;
    case 7: r = v / 3.280840; break;
    case 8: r = v / 2.54; break;
    case 9: r = v * 2.54; break;
    case 10: r = v / 3.6; break;
    case 11: r = v * 3.6; break;
  }
  char a[20], b[20];
  fmtNum(v, a, 20); fmtNum(r, b, 20);
  Lc();
  La("%s", it[o]);
  La("");
  La("%s", a);
  La("= %s", b);
  visor("CONVERSOR");
}

void herrBinHex() {
  double v;
  if (!pedirNum("NUMERO ENTERO (DEC)", v)) return;
  if (v < 0 || v > 2000000000.0 || v != floor(v)) { sonidoError(); mensaje("ENTERO DE 0 A", "2000000000"); delay(1400); return; }
  unsigned long n = (unsigned long)v;
  Lc();
  La("DEC = %lu", n);
  char bin[34]; int k = 0;
  if (n == 0) bin[k++] = '0';
  else { char t[34]; int m = 0; unsigned long x = n; while (x) { t[m++] = '0' + (x & 1); x >>= 1; } while (m) bin[k++] = t[--m]; }
  bin[k] = 0;
  if (k <= 17) La("BIN = %s", bin);
  else { La("BIN (%d BITS):", k); char p1[22]; strncpy(p1, bin, 21); p1[21] = 0; La("%s", p1); if (k > 21) La("%s", bin + 21); }
  La("HEX = %lX", n);
  La("OCT = %lo", n);
  visor("BIN / HEX");
}

void herrMcd() {
  double a, b;
  if (!pedirNum("PRIMER ENTERO", a)) return;
  if (!pedirNum("SEGUNDO ENTERO", b)) return;
  long x = (long)a, y = (long)b;
  if (x < 1 || y < 1 || a != floor(a) || b != floor(b) || a > 1e9 || b > 1e9) {
    sonidoError(); mensaje("ENTEROS POSITIVOS", "DE 1 A 1000000000"); delay(1400); return;
  }
  long g = mcdL(x, y);
  Lc();
  La("MCD = %ld", g);
  La("MCM = %lld", (long long)x / g * (long long)y);
  char f[24];
  factoresPrimos(x, f, sizeof(f)); La("%ld:", x); La(" %s", f);
  factoresPrimos(y, f, sizeof(f)); La("%ld:", y); La(" %s", f);
  visor("MCD / MCM");
}

