  const char* it[] = {"EXPRESION", "TABLA DE MULT.", "PORCENTAJE", "REGLA DE 3", "ECUACION 2o GRADO",
                      "SISTEMA 2x2", "GEOMETRIA", "ESTADISTICA", "CONVERSOR", "BINARIO / HEX",
