void buscarRedes() {
  mensaje("BUSCANDO REDES...");
  int n = WiFi.scanNetworks();
  if (n <= 0) { WiFi.scanDelete(); sonidoError(); mensaje("NO HAY REDES", "(SOLO 2.4 GHz)"); delay(1500); return; }
  char nombres[12][34]; int rssi[12]; bool segura[12]; int m = 0;
  for (int i = 0; i < n && m < 12; i++) {
    String s = WiFi.SSID(i);
    if (s.length() == 0) continue;
    bool dup = false;
    for (int j = 0; j < m; j++) if (!strcmp(nombres[j], s.c_str())) dup = true;
    if (dup) continue;
    strncpy(nombres[m], s.c_str(), 33); nombres[m][33] = 0;
    rssi[m] = WiFi.RSSI(i);
    segura[m] = (WiFi.encryptionType(i) != WIFI_AUTH_OPEN);
    m++;
  }
  WiFi.scanDelete();
