// ---- Encender el PC (Wake-on-LAN) ----
WiFiUDP udp;
bool macValida(const String& m, uint8_t* mac) {
  if (m.length() != 17) return false;
  for (int i = 0; i < 6; i++) {
    int p = i * 3;
    if (i < 5 && m[p + 2] != ':' && m[p + 2] != '-') return false;
    if (!isxdigit((unsigned char)m[p]) || !isxdigit((unsigned char)m[p + 1])) return false;
    char h[3] = {m[p], m[p + 1], 0};
    mac[i] = (uint8_t)strtol(h, nullptr, 16);
  }
  return true;
}

void webPC() {
  uint8_t mac[6];
  String m = servidor.arg("m"); m.trim();
  if (!m.length()) {
    char b[20]; b[0] = 0;
    prefs.begin("flanpet", true); prefs.getString("pcm", b, sizeof(b)); prefs.end();
    m = b;
  }
  if (!macValida(m, mac)) { servidor.send(200, "text/plain", "MAC no valida. Formato: AA:BB:CC:DD:EE:FF"); return; }
  prefs.begin("flanpet", false); prefs.putString("pcm", m.c_str()); prefs.end();
  if (servidor.arg("enc") != "1") { servidor.send(200, "text/plain", "MAC guardada."); return; }
  if (apActivo() || WiFi.status() != WL_CONNECTED) { servidor.send(200, "text/plain", "Necesito estar en tu WiFi de casa (misma red que el PC)."); return; }
  uint8_t pkt[102];
  memset(pkt, 0xFF, 6);
  for (int i = 0; i < 16; i++) memcpy(pkt + 6 + i * 6, mac, 6);
  for (int k = 0; k < 3; k++) { udp.beginPacket(WiFi.broadcastIP(), 9); udp.write(pkt, sizeof(pkt)); udp.endPacket(); delay(40); }
  servidor.send(200, "text/plain", "Senal enviada. Si tu PC tiene Wake-on-LAN activado, enciende en unos segundos.");
}
