void armarLineas(int cols) {
  nLineas = 0;
  int n = strlen(resp), i = 0;
  while (i < n && nLineas < 79) {
    while (i < n && resp[i] == ' ') i++;
    if (i >= n) break;
    lineasIni[nLineas++] = i;
    int fin = i + cols;
    if (fin >= n) { i = n; break; }
    int corte = fin;
    while (corte > i && resp[corte] != ' ') corte--;
    if (corte == i) corte = fin;
    i = corte;
  }
  lineasIni[nLineas] = n;
}

