// ---- Respuesta letra por letra con paginas ----
void iaPantallaRespuesta(const char* titulo) {
  armarLineas(20);
  int paginas = (nLineas + 4) / 5;
  if (paginas < 1) paginas = 1;
  int pag = 0, rev = 0, dibAntes = 0;
  gestoUsado = true;
  while (true) {
    iaFondo();
    int primera = pag * 5, ultima = primera + 5; if (ultima > nLineas) ultima = nLineas;
    int totalPag = 0;
    for (int l = primera; l < ultima; l++) {
      int len = lineasIni[l + 1] - lineasIni[l];
      if (len > 20) len = 20;
      totalPag += len;
    }
    int g = gesto();
    if (g == 2) { emitirSonido(1000, 50); return; }
    if (g == 1) {
      if (rev < totalPag) rev = totalPag;                        // toque = mostrar todo
      else if (pag + 1 >= paginas) { emitirSonido(900, 30); return; }
      else { pag++; rev = 0; dibAntes = 0; emitirSonido(900, 30); continue; }
    }
    if (rev < totalPag) rev += 2;
    if (rev > totalPag) rev = totalPag;

    disp.clearDisplay();
    char der[12]; snprintf(der, sizeof(der), "%d/%d", pag + 1, paginas);
    cabecera(titulo, der);
    disp.setTextSize(1);
    int quedan = rev, dib = 0;
    char ultCh = ' ';
    for (int l = primera; l < ultima && quedan > 0; l++) {
      int a = lineasIni[l], b = lineasIni[l + 1];
      if (b - a > 20) b = a + 20;
      disp.setCursor(0, 14 + (l - primera) * 8);
      for (int i = a; i < b && quedan > 0; i++, quedan--) { disp.print(resp[i]); ultCh = resp[i]; dib++; }
    }
    if (dib > dibAntes) { nuevaMelodia(); nota(1100 + (ultCh % 9) * 90, 10); dibAntes = dib; }
    if (paginas > 1) {                                           // barra de avance
      disp.drawFastVLine(126, 13, 40, SSD1306_WHITE);
      int h = 40 / paginas; if (h < 5) h = 5;
      int yb = 13 + (40 - h) * pag / (paginas - 1);
      disp.fillRect(125, yb, 3, h, SSD1306_WHITE);
    }
    pie(rev < totalPag ? "NAV=VER TODO" : (pag + 1 >= paginas ? "NAV U OK=SALIR" : "NAV=SIG OK=SALIR"));
    disp.display();
    delay(25);
  }
}

