// ---- Pomodoro ----
void iaTemporizador(const char* nom, unsigned long dur) {
  unsigned long acum = 0, ult = millis();
  bool pausa = false;
  gestoUsado = true;
  while (true) {
    iaFondo();
    unsigned long ahora = millis();
    if (!pausa) acum += ahora - ult;
    ult = ahora;
    int g = gesto();
    if (g == 2) { emitirSonido(1000, 50); return; }
    if (g == 1) { pausa = !pausa; emitirSonido(900, 30); }
    if (acum >= dur) {
      nuevaMelodia();
      for (int i = 0; i < 3; i++) { nota(1800, 120); nota(0, 80); nota(2400, 200); nota(0, 150); }
      disp.clearDisplay();
      disp.setTextColor(SSD1306_WHITE);
      disp.setTextSize(2);
      disp.setCursor(34, 12); disp.print("LISTO!");
      disp.setTextSize(1);
      centrado(nom, 36);
      pie("OK O NAV=SALIR");
      disp.display();
      iaEsperaToque();
      return;
    }
    unsigned long resta = (dur - acum) / 1000UL;
    char t[8]; snprintf(t, sizeof(t), "%02lu:%02lu", resta / 60, resta % 60);
    disp.clearDisplay();
    cabecera(nom, pausa ? "PAUSA" : "");
    disp.setTextColor(SSD1306_WHITE);
    disp.setTextSize(3);
    disp.setCursor(22, 18); disp.print(t);
    disp.setTextSize(1);
    disp.drawRect(10, 44, 108, 6, SSD1306_WHITE);
    disp.fillRect(12, 46, (int)(104UL * acum / dur), 2, SSD1306_WHITE);
    pie("NAV=PAUSA OK=SALIR");
    disp.display();
    delay(50);
  }
}
void iaPomodoro() {
  const char* it[4] = {"ENFOQUE 25 MIN", "DESCANSO 5 MIN", "ENFOQUE 50 MIN", "< VOLVER"};
  int ult = 0;
  while (true) {
    int o = iaLista("POMODORO", it, 4, ult);
    ult = o;
    if (o == 3) return;
    unsigned long minutos = (o == 0) ? 25 : (o == 1) ? 5 : 50;
    iaTemporizador(o == 1 ? "DESCANSO" : "ENFOQUE", minutos * 60000UL);
  }
}

// ---- Menu de Flan IA ----
void iaMenu() {
  int ult = 0;
  while (true) {
    char modoTxt[24];
    snprintf(modoTxt, sizeof(modoTxt), "MODO: %s", IA_MODOS[iaModo]);
    const char* it[9] = {"CHAT IA", modoTxt, "QUIZ IA", "EXTRAS", "NOTAS", "POMODORO", "PREGUNTAS WEB", "NUEVO CHAT", "< VOLVER"};
    int o = iaLista("FLAN IA", it, 9, ult);
    ult = o;
    switch (o) {
      case 0: chatIA(); break;
      case 1: {
        int m = elegirLista("MODO DE IA", IA_MODOS, 5, false, iaModo);
        if (m != iaModo) { iaModo = m; nHist = 0; }              // al cambiar de modo empieza chat nuevo
        break;
      }
      case 2: quizIA(); break;
      case 3: iaExtras(); break;
      case 4: pantallaNotas(); break;
      case 5: iaPomodoro(); break;
      case 6: iaPreguntasWeb(); break;
      case 7: nHist = 0; mensaje("CHAT NUEVO", "MEMORIA BORRADA"); delay(900); break;
      default: return;
    }
  }
}
void tickIA() {
  switch (herrSel) {
    case 0: iaMenu(); break;
    case 1: menuCalculadora(); break;
    case 2: menuRedes(); break;
    case 3: menuAjustes(); break;
    default: pantallaSistema(); break;
  }
  abrirMenu();
}

// ---- Web de Flan IA ----
void webPreguntar() {
  String q = asciiLimpio(servidor.arg("q")); q.trim();
  int m = constrain(servidor.arg("m").toInt(), 0, 4);
  if (!q.length()) { servidor.send(200, "text/plain", "Escribe una pregunta."); return; }
  if (!hayKey()) { servidor.send(200, "text/plain", "Falta la API key. Pegala en la seccion Gemini API key."); return; }
  if (enLlamada) { servidor.send(200, "text/plain", "Estoy ocupado, intenta otra vez."); return; }
  if (modo == M_JUEGO) { servidor.send(200, "text/plain", "Estoy en un juego, espera a que termine."); return; }
  if (q.length() > 200) q = q.substring(0, 200);
  q.replace("\"", "'");
  static char gResp[sizeof(resp)]; static int gLin[80];          // guardamos lo que estaba usando la pantalla
  int gN = nLineas;
  memcpy(gResp, resp, sizeof(resp)); memcpy(gLin, lineasIni, sizeof(lineasIni));
  if (modo == M_PET && pagina == 0) {                              // la carita se pone a pensar
    forzarAnimo(A_PENSANDO, 30000UL);
    animoPrev = A_PENSANDO; animoIni = millis();
    dibujar();
  }
  int e = iaPedir(IA_MODOS_SYS[m], q.c_str(), 1500, true, true);
  ovr = -1;
  String out;
  if (e == 0) { agregarHist(q.c_str(), resp); iaAnotar(q.c_str(), resp); out = resp; emitirSonido(2000, 60); }
  else out = String("Error ") + e + ": " + textoError(e);
  memcpy(resp, gResp, sizeof(resp)); memcpy(lineasIni, gLin, sizeof(lineasIni)); nLineas = gN;
  servidor.send(200, "text/plain", out);
}
void webMensaje() {
  String m = asciiLimpio(servidor.arg("m")); m.trim();
  if (!m.length()) { servidor.send(200, "text/plain", "Vacio"); return; }
  if (m.length() > 100) m = m.substring(0, 100);
  strncpy(msgWeb, m.c_str(), sizeof(msgWeb) - 1); msgWeb[sizeof(msgWeb) - 1] = 0;
  msgPend = true;
  servidor.send(200, "text/plain", "Enviado");
}
void webNotas() {
  String j = "[";
  for (int i = 0; i < 5; i++) {
    char txt[NOTA_MAX + 4]; iaLeerNota(i, txt, sizeof(txt));
    if (i) j += ",";
    j += "\""; j += jEsc(txt); j += "\"";
  }
  j += "]";
  servidor.send(200, "application/json", j);
}
void webNotaGuardar() {
  int i = servidor.arg("i").toInt();
  String t = asciiLimpio(servidor.arg("t")); t.trim();
  if (i < 0 || i > 4) { servidor.send(200, "text/plain", "?"); return; }
  if (t.length() > NOTA_MAX) t = t.substring(0, NOTA_MAX);
  char k[4]; snprintf(k, sizeof(k), "n%d", i);
  prefs.begin("flania", false);
  if (t.length()) prefs.putString(k, t.c_str()); else prefs.remove(k);
  prefs.end();
  servidor.send(200, "text/plain", "OK");
}
void webRegistro() {
  String j = "[";
  for (int i = iaNReg - 1; i >= 0; i--) {
    if (i != iaNReg - 1) j += ",";
    j += "{\"q\":\""; j += jEsc(iaReg[i].q); j += "\",\"a\":\""; j += jEsc(iaReg[i].a); j += "\"}";
  }
  j += "]";
  servidor.send(200, "application/json", j);
}
